CREATE OR ALTER PROCEDURE etl.usp_load_fact_sales_line @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    BEGIN TRANSACTION;   -- full rebuild is atomic: Power BI never reads a half-loaded fact
        TRUNCATE TABLE dw.fact_sales_line;
        INSERT INTO dw.fact_sales_line (sales_order_id, sales_order_detail_id, sales_order_number, order_date_key, ship_date_key, due_date_key, customer_key, product_key, territory_key, salesperson_key, special_offer_key, ship_method_key, order_channel, order_status, order_quantity, unit_price, unit_price_discount_pct, gross_sales_amount, discount_amount, net_sales_amount, standard_cost_amount, gross_margin_amount, allocated_freight_amount, allocated_tax_amount)
        SELECT d.SalesOrderID       AS sales_order_id,
               d.SalesOrderDetailID AS sales_order_detail_id,
               h.SalesOrderNumber   AS sales_order_number,
               YEAR(h.OrderDate) * 10000 + MONTH(h.OrderDate) * 100 + DAY(h.OrderDate) AS order_date_key,
               CASE WHEN h.ShipDate IS NULL THEN NULL ELSE YEAR(h.ShipDate) * 10000 + MONTH(h.ShipDate) * 100 + DAY(h.ShipDate) END AS ship_date_key,
               YEAR(h.DueDate) * 10000 + MONTH(h.DueDate) * 100 + DAY(h.DueDate) AS due_date_key,
               COALESCE(dc.customer_key, -1)      AS customer_key,
               COALESCE(dp.product_key, -1)       AS product_key,
               COALESCE(dt.territory_key, -1)     AS territory_key,
               COALESCE(dsp.salesperson_key, -1)  AS salesperson_key,
               COALESCE(dso.special_offer_key, -1) AS special_offer_key,
               COALESCE(dsm.ship_method_key, -1)  AS ship_method_key,
               CASE WHEN h.OnlineOrderFlag = 1 THEN N'Online' ELSE N'Reseller' END AS order_channel,
               CASE h.Status WHEN 1 THEN N'In process' WHEN 2 THEN N'Approved' WHEN 3 THEN N'Backordered' WHEN 4 THEN N'Rejected' WHEN 5 THEN N'Shipped' WHEN 6 THEN N'Cancelled' ELSE N'Unknown' END AS order_status,
               d.OrderQty           AS order_quantity,
               d.UnitPrice          AS unit_price,
               d.UnitPriceDiscount  AS unit_price_discount_pct,
               CAST(d.OrderQty * d.UnitPrice AS DECIMAL(19,6))                                        AS gross_sales_amount,
               CAST(d.OrderQty * d.UnitPrice - d.LineTotal AS DECIMAL(19,6))                          AS discount_amount,
               CAST(d.LineTotal AS DECIMAL(19,6))                                                     AS net_sales_amount,
               CAST(d.OrderQty * COALESCE(c.StandardCost, p.StandardCost, 0) AS DECIMAL(19,6))        AS standard_cost_amount,
               CAST(d.LineTotal - d.OrderQty * COALESCE(c.StandardCost, p.StandardCost, 0) AS DECIMAL(19,6)) AS gross_margin_amount,
               CAST(CAST(h.Freight AS DECIMAL(19,6)) * CAST(d.LineTotal AS DECIMAL(19,6)) / CAST(NULLIF(h.SubTotal, 0) AS DECIMAL(19,6)) AS DECIMAL(19,6)) AS allocated_freight_amount,
               CAST(CAST(h.TaxAmt AS DECIMAL(19,6)) * CAST(d.LineTotal AS DECIMAL(19,6)) / CAST(NULLIF(h.SubTotal, 0) AS DECIMAL(19,6)) AS DECIMAL(19,6)) AS allocated_tax_amount
        FROM stg.SalesOrderDetail AS d
        JOIN stg.SalesOrderHeader AS h ON h.SalesOrderID = d.SalesOrderID
        LEFT JOIN stg.Product AS p ON p.ProductID = d.ProductID
        LEFT JOIN stg.ProductCostHistory AS c
               ON c.ProductID = d.ProductID AND h.OrderDate >= c.StartDate AND (c.EndDate IS NULL OR h.OrderDate <= c.EndDate)
        LEFT JOIN dw.dim_customer      AS dc  ON dc.customer_id = h.CustomerID
        LEFT JOIN dw.dim_product       AS dp  ON dp.product_id = d.ProductID
        LEFT JOIN dw.dim_territory     AS dt  ON dt.territory_id = h.TerritoryID
        LEFT JOIN dw.dim_salesperson   AS dsp ON dsp.business_entity_id = h.SalesPersonID
        LEFT JOIN dw.dim_special_offer AS dso ON dso.special_offer_id = d.SpecialOfferID
        LEFT JOIN dw.dim_ship_method   AS dsm ON dsm.ship_method_id = h.ShipMethodID;
        SET @rows = @@ROWCOUNT;
    COMMIT TRANSACTION;

    EXEC etl.usp_log_step @run_id, N'load fact_sales_line', @t0, @rows;
END;
GO
CREATE OR ALTER PROCEDURE etl.usp_load_fact_sales_quota @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    BEGIN TRANSACTION;   -- full rebuild is atomic: Power BI never reads a half-loaded fact
        TRUNCATE TABLE dw.fact_sales_quota;
        INSERT INTO dw.fact_sales_quota (quota_month_key, salesperson_key, territory_key, quota_amount)
        SELECT m.date_key AS quota_month_key,
               COALESCE(dsp.salesperson_key, -1) AS salesperson_key,
               COALESCE(dt.territory_key, -1)    AS territory_key,
               CAST(q.SalesQuota / 3.0 AS DECIMAL(19,6)) AS quota_amount
        FROM stg.SalesPersonQuotaHistory AS q
        JOIN dw.dim_date AS m
          ON m.calendar_year = YEAR(q.QuotaDate)
         AND m.quarter_number = CASE WHEN MONTH(q.QuotaDate) <= 3 THEN 1 WHEN MONTH(q.QuotaDate) <= 6 THEN 2 WHEN MONTH(q.QuotaDate) <= 9 THEN 3 ELSE 4 END
         AND m.day_of_month = 1
        LEFT JOIN stg.SalesPerson AS sp ON sp.BusinessEntityID = q.BusinessEntityID
        LEFT JOIN dw.dim_salesperson AS dsp ON dsp.business_entity_id = q.BusinessEntityID
        LEFT JOIN dw.dim_territory AS dt ON dt.territory_id = sp.TerritoryID;
        SET @rows = @@ROWCOUNT;
    COMMIT TRANSACTION;

    EXEC etl.usp_log_step @run_id, N'load fact_sales_quota', @t0, @rows;
END;
GO
CREATE OR ALTER PROCEDURE etl.usp_load_fact_purchase_line @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    BEGIN TRANSACTION;   -- full rebuild is atomic: Power BI never reads a half-loaded fact
        TRUNCATE TABLE dw.fact_purchase_line;
        INSERT INTO dw.fact_purchase_line (purchase_order_id, purchase_order_detail_id, order_date_key, ship_date_key, due_date_key, vendor_key, product_key, ship_method_key, territory_key, order_status, order_quantity, received_quantity, rejected_quantity, stocked_quantity, unit_price, line_total_amount, allocated_freight_amount, allocated_tax_amount, shipped_flag, on_time_flag, days_late)
        SELECT d.PurchaseOrderID       AS purchase_order_id,
               d.PurchaseOrderDetailID AS purchase_order_detail_id,
               YEAR(h.OrderDate) * 10000 + MONTH(h.OrderDate) * 100 + DAY(h.OrderDate) AS order_date_key,
               CASE WHEN h.ShipDate IS NULL THEN NULL ELSE YEAR(h.ShipDate) * 10000 + MONTH(h.ShipDate) * 100 + DAY(h.ShipDate) END AS ship_date_key,
               YEAR(d.DueDate) * 10000 + MONTH(d.DueDate) * 100 + DAY(d.DueDate) AS due_date_key,
               COALESCE(dv.vendor_key, -1)      AS vendor_key,
               COALESCE(dp.product_key, -1)     AS product_key,
               COALESCE(dsm.ship_method_key, -1) AS ship_method_key,
               COALESCE(dv.territory_key, -1)   AS territory_key,
               CASE h.Status WHEN 1 THEN N'Pending' WHEN 2 THEN N'Approved' WHEN 3 THEN N'Rejected' WHEN 4 THEN N'Complete' ELSE N'Unknown' END AS order_status,
               d.OrderQty     AS order_quantity,
               d.ReceivedQty  AS received_quantity,
               d.RejectedQty  AS rejected_quantity,
               d.StockedQty   AS stocked_quantity,
               d.UnitPrice    AS unit_price,
               CAST(d.LineTotal AS DECIMAL(19,6)) AS line_total_amount,
               CAST(CAST(h.Freight AS DECIMAL(19,6)) * CAST(d.LineTotal AS DECIMAL(19,6)) / CAST(NULLIF(h.SubTotal, 0) AS DECIMAL(19,6)) AS DECIMAL(19,6)) AS allocated_freight_amount,
               CAST(CAST(h.TaxAmt AS DECIMAL(19,6)) * CAST(d.LineTotal AS DECIMAL(19,6)) / CAST(NULLIF(h.SubTotal, 0) AS DECIMAL(19,6)) AS DECIMAL(19,6)) AS allocated_tax_amount,
               CASE WHEN h.ShipDate IS NULL THEN 0 ELSE 1 END AS shipped_flag,
               CASE WHEN h.ShipDate IS NOT NULL AND h.ShipDate <= d.DueDate THEN 1 ELSE 0 END AS on_time_flag,
               CASE WHEN h.ShipDate IS NOT NULL AND h.ShipDate > d.DueDate THEN DATEDIFF(DAY, d.DueDate, h.ShipDate) ELSE 0 END AS days_late
        FROM stg.PurchaseOrderDetail AS d
        JOIN stg.PurchaseOrderHeader AS h ON h.PurchaseOrderID = d.PurchaseOrderID
        LEFT JOIN dw.dim_vendor      AS dv  ON dv.vendor_id = h.VendorID
        LEFT JOIN dw.dim_product     AS dp  ON dp.product_id = d.ProductID
        LEFT JOIN dw.dim_ship_method AS dsm ON dsm.ship_method_id = h.ShipMethodID;
        SET @rows = @@ROWCOUNT;
    COMMIT TRANSACTION;

    EXEC etl.usp_log_step @run_id, N'load fact_purchase_line', @t0, @rows;
END;
GO
CREATE OR ALTER PROCEDURE etl.usp_load_fact_inventory @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    BEGIN TRANSACTION;   -- full rebuild is atomic: Power BI never reads a half-loaded fact
        TRUNCATE TABLE dw.fact_inventory;
        INSERT INTO dw.fact_inventory (product_key, location_key, quantity, inventory_value_amount)
        SELECT dp.product_key AS product_key, dl.location_key AS location_key,
               i.Quantity AS quantity,
               CAST(i.Quantity * dp.standard_cost AS DECIMAL(19,4)) AS inventory_value_amount
        FROM stg.ProductInventory AS i
        JOIN dw.dim_product  AS dp ON dp.product_id = i.ProductID
        JOIN dw.dim_location AS dl ON dl.location_id = i.LocationID;
        SET @rows = @@ROWCOUNT;
    COMMIT TRANSACTION;

    EXEC etl.usp_log_step @run_id, N'load fact_inventory', @t0, @rows;
END;
