CREATE OR ALTER PROCEDURE etl.usp_load_fact_headcount_monthly @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    BEGIN TRANSACTION;   -- full rebuild is atomic: Power BI never reads a half-loaded fact
        TRUNCATE TABLE dw.fact_headcount_monthly;
        INSERT INTO dw.fact_headcount_monthly (month_end_date_key, employee_key, department_key, territory_key, headcount_flag, new_hire_flag, tenure_months)
        SELECT m.date_key AS month_end_date_key,
               e.employee_key AS employee_key,
               COALESCE(dd.department_key, -1) AS department_key,
               e.territory_key AS territory_key,
               1 AS headcount_flag,
               CASE WHEN e.hire_date >= m.month_start_date THEN 1 ELSE 0 END AS new_hire_flag,
               DATEDIFF(MONTH, e.hire_date, m.full_date) AS tenure_months
        FROM dw.dim_date AS m
        JOIN dw.dim_employee AS e ON e.hire_date <= m.full_date AND e.current_status = N'Current' AND e.employee_key <> -1
        LEFT JOIN stg.EmployeeDepartmentHistory AS h
               ON h.BusinessEntityID = e.business_entity_id AND h.StartDate <= m.full_date AND (h.EndDate IS NULL OR h.EndDate >= m.full_date)
        LEFT JOIN dw.dim_department AS dd ON dd.department_id = h.DepartmentID
        WHERE m.is_month_end = 1;
        SET @rows = @@ROWCOUNT;
    COMMIT TRANSACTION;

    EXEC etl.usp_log_step @run_id, N'load fact_headcount_monthly', @t0, @rows;
END;
GO
CREATE OR ALTER PROCEDURE etl.usp_load_fact_payroll_monthly @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    BEGIN TRANSACTION;   -- full rebuild is atomic: Power BI never reads a half-loaded fact
        TRUNCATE TABLE dw.fact_payroll_monthly;
        INSERT INTO dw.fact_payroll_monthly (month_end_date_key, department_key, territory_key, employee_count, estimated_payroll_cost)
        SELECT hc.month_end_date_key AS month_end_date_key,
               hc.department_key AS department_key,
               hc.territory_key AS territory_key,
               COUNT(*) AS employee_count,
               CAST(SUM(COALESCE(r.Rate, 0) * 173.3333) AS DECIMAL(19,4)) AS estimated_payroll_cost
        FROM dw.fact_headcount_monthly AS hc
        JOIN dw.dim_date AS m ON m.date_key = hc.month_end_date_key
        JOIN dw.dim_employee AS e ON e.employee_key = hc.employee_key
        LEFT JOIN stg.EmployeePayHistory AS r
               ON r.BusinessEntityID = e.business_entity_id
              AND r.RateChangeDate = (SELECT MAX(r2.RateChangeDate) FROM stg.EmployeePayHistory AS r2
                                      WHERE r2.BusinessEntityID = e.business_entity_id AND r2.RateChangeDate <= m.full_date)
        GROUP BY hc.month_end_date_key, hc.department_key, hc.territory_key;
        SET @rows = @@ROWCOUNT;
    COMMIT TRANSACTION;

    EXEC etl.usp_log_step @run_id, N'load fact_payroll_monthly', @t0, @rows;
END;
GO
